    "campaignsDetailsRow3": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041E\u0436\u0438\u0432\u0456\u0442\u044C \u0441\u0432\u0456\u0439 \u0431\u0456\u0437\u043D\u0435\u0441 \u0442\u0430 \u0437\u0430\u0445\u043E\u043F\u0456\u0442\u044C \u0430\u0443\u0434\u0438\u0442\u043E\u0440\u0456\u044E \u0434\u0438\u043D\u0430\u043C\u0456\u0447\u043D\u0438\u043C \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u043E\u043C \u0431\u0440\u0435\u043D\u0434\u0443, \u044F\u043A\u0438\u0439 \u0456\u0434\u0435\u0430\u043B\u044C\u043D\u043E \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u0430\u0454 \u0441\u0443\u0447\u0430\u0441\u043D\u0438\u043C \u0440\u0438\u043D\u043A\u043E\u0432\u0438\u043C \u0442\u0435\u043D\u0434\u0435\u043D\u0446\u0456\u044F\u043C \u0442\u0430 \u0431\u0430\u0436\u0430\u043D\u043D\u044F\u043C \u043A\u043B\u0456\u0454\u043D\u0442\u0456\u0432." } },
